#include <vector>
#include <unordered_set>
using namespace std;

class Solution {
public:
    int minOperationsToDistinct(vector<int>& nums) {
        int n = nums.size();
        int ops = 0;
        while (3 * ops < n) {
            unordered_set<int> seen;
            bool unique = true;
            for (int i = 3 * ops; i < n; i++) {
                if (seen.count(nums[i])) {
                    unique = false;
                    break;
                }
                seen.insert(nums[i]);
            }
            if (unique) return ops;
            ops++;
        }
        return ops;
    }
};

import java.util.*;

class Solution {
    public int minOperationsToDistinct(int[] nums) {
        int n = nums.length;
        int ops = 0;
        while (3 * ops < n) {
            Set<Integer> seen = new HashSet<>();
            boolean unique = true;
            for (int i = 3 * ops; i < n; i++) {
                if (!seen.add(nums[i])) {
                    unique = false;
                    break;
                }
            }
            if (unique) return ops;
            ops++;
        }
        return ops;
    }
}

var minOperationsToDistinct = function(nums) {
    let ops = 0;
    while (3 * ops < nums.length) {
        const suffix = nums.slice(3 * ops);
        if (new Set(suffix).size === suffix.length) return ops;
        ops++;
    }
    return ops;
};
